{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative or neutral, especially after recent spikes.",
    "Reduce forecast overshoots by 10-15% in the immediate post-spike period.",
    "Apply mean reversion bias: if 3-5 consecutive days show upward drift, slightly dampen forecast growth.",
    "Increase forecast sensitivity to sentiment spikes: if sentiment > 0.5, raise forecast by 5-10% for next 3 days.",
    "Lag correction: if true outcome is higher than forecast, adjust next forecast down by 2-5% to avoid overcorrection.",
    "Avoid overreacting to short-term volatility: if sentiment is low and price is volatile, use 30-day moving average as anchor."
  ]
}
